package dominoes

// Domino represents a domino tile: a pair of values, one on each half.
type Domino [2]int

// MakeChain reports whether the given dominoes can be arranged into a valid
// closed chain, in which case it returns one such chain.
//
// A chain is valid when the two halves of adjacent dominoes match and the
// two free ends of the chain (the first and last domino) also match.
// Every input domino is used exactly once, and a domino may be flipped.
func MakeChain(input []Domino) ([]Domino, bool) {
	if len(input) == 0 {
		return []Domino{}, true
	}

	// Work on a copy so the caller's slice is left untouched.
	dominoes := make([]Domino, len(input))
	copy(dominoes, input)

	// Any closed chain can be rotated to start with any of its dominoes,
	// so it is enough to try the first input domino as the chain's start,
	// in both orientations.
	for _, start := range [][2]int{
		{dominoes[0][0], dominoes[0][1]},
		{dominoes[0][1], dominoes[0][0]},
	} {
		chain := []Domino{Domino(start)}
		if len(dominoes) == 1 {
			// A lone domino is a closed chain only if both halves match.
			if chain[0][0] == chain[0][1] {
				return chain, true
			}
			continue
		}
		if search(dominoes[1:], &chain) {
			return chain, true
		}
	}
	return nil, false
}

// search tries to extend chain with the remaining dominoes (in either
// orientation) until all are used. It returns true when the completed
// chain is closed, i.e. its free ends match.
func search(remaining []Domino, chain *[]Domino) bool {
	if len(remaining) == 0 {
		return (*chain)[0][0] == (*chain)[len(*chain)-1][1]
	}

	last := (*chain)[len(*chain)-1][1]
	for i := 0; i < len(remaining); i++ {
		d := remaining[i]
		orientations := [][2]int{{d[0], d[1]}, {d[1], d[0]}}
		if d[0] == d[1] {
			orientations = orientations[:1] // flipping a double is a no-op
		}
		for _, o := range orientations {
			if o[0] != last {
				continue
			}
			*chain = append(*chain, Domino(o))
			// Swap the chosen domino out of remaining for the recursion.
			remaining[i] = remaining[len(remaining)-1]
			if search(remaining[:len(remaining)-1], chain) {
				return true
			}
			// Undo the swap and the chain extension.
			remaining[i] = d
			*chain = (*chain)[:len(*chain)-1]
		}
	}
	return false
}

